void dfs(vector<vector<int>> &mat, int i, int j, int time)
{
    int n = mat.size();
    int m = mat[0].size();

    // update minimum time
    mat[i][j] = time;

    // all four directions
    vector<vector<int>> directions = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

