    for (auto dir : directions)
    {
        int x = i + dir[0];
        int y = j + dir[1];

        // if cell is in the matrix and
        // the orange is fresh
        if (isSafe(x, y, n, m) && (mat[x][y] == 1 || mat[x][y] > time + 1))
        {
            dfs(mat, x, y, time + 1);
        }
    }
}

